#!/usr/bin/env node
// Install a pre-commit hook that refuses commits under a foreign identity.
// Hooks are not versioned, so run this once per clone: node scripts/install_hooks.mjs
import { writeFileSync, chmodSync, existsSync } from 'node:fs';

const hookPath = '.git/hooks/pre-commit';
if (!existsSync('.git')) {
  console.error('Run this from the repository root.');
  process.exit(2);
}

const hook = `#!/bin/sh
# Generated by scripts/install_hooks.mjs. August reviews rejected a submission
# because the repository contained commits by another person; this repo pins
# one identity and fails the commit instead of misattributing it.
expected_name="LMK-ai-nb"
expected_email="315346758+LMK-ai-nb@users.noreply.github.com"
local_name="$(git config --local --get user.name)"
local_email="$(git config --local --get user.email)"
author_email="\${GIT_AUTHOR_EMAIL:-$local_email}"
committer_email="\${GIT_COMMITTER_EMAIL:-$local_email}"
if [ "$local_name" != "$expected_name" ] || [ "$local_email" != "$expected_email" ] || \\
   [ "$author_email" != "$expected_email" ] || [ "$committer_email" != "$expected_email" ]; then
  echo "ERROR: wrong git identity for this repository." >&2
  echo "  local:     $local_name <$local_email>" >&2
  echo "  author:    $author_email" >&2
  echo "  committer: $committer_email" >&2
  echo "  expected:  $expected_name <$expected_email>" >&2
  echo "Fix: git config --local user.name \\"$expected_name\\"" >&2
  echo "     git config --local user.email \\"$expected_email\\"" >&2
  exit 1
fi
exit 0
`;

writeFileSync(hookPath, hook);
chmodSync(hookPath, 0o755);
console.log(`Installed ${hookPath}`);
console.log('It blocks commits whose local, author or committer identity is not LMK-ai-nb.');
